<div class="container-fluid account-admin">
<h1>Akun & undangan</h1><p>Anggota yang menerima undangan mendapat akses pengguna ke workspace ini.</p>
<?php foreach(get_flashes() as $flash): ?><div class="alert alert-<?= $flash['type']==='error'?'danger':'success' ?>" role="status"><?= e($flash['message']) ?></div><?php endforeach; ?>
<?php if($actor['verified_channel']===null): ?>
<div class="card mb-4"><div class="card-body"><h2 class="h5">Verifikasi tujuan pemulihan</h2><p>Konfirmasikan email atau WhatsApp yang tercatat sebelum menggunakan pemulihan kata sandi. Administrator platform perlu mengatur kanal notifikasi terlebih dahulu.</p><form method="POST" action="<?= e(base_url('account/resend')) ?>"><?= csrf_field() ?><input type="hidden" name="identifier" value="<?= e($actor['email']) ?>"><button type="submit" class="btn btn-primary">Verifikasi tujuan pemulihan</button></form></div></div>
<?php else: ?><p class="text-muted">Tujuan pemulihan telah terverifikasi melalui <?= $actor['verified_channel']==='starsender'?'WhatsApp':'email' ?>.</p><?php endif; ?>
<div class="card mb-4"><div class="card-body"><h2 class="h5">Undang anggota tim</h2><form method="POST" action="<?= e(base_url('account/invite')) ?>"><?= csrf_field() ?><div class="row g-3"><div class="col-md-5"><label for="invite-email" class="form-label">Email anggota</label><input id="invite-email" type="email" name="email" class="form-control" required maxlength="100"></div><div class="col-md-5"><label for="invite-phone" class="form-label">WhatsApp (untuk kanal WhatsApp)</label><input id="invite-phone" name="phone" type="tel" class="form-control" maxlength="30"></div><div class="col-md-2"><button type="submit" class="btn btn-primary mt-4">Kirim undangan</button></div></div><p class="text-muted mt-3">Undangan berlaku 48 jam. Email, kanal, dan workspace terkunci dalam undangan.</p></form></div></div>
<div class="card mb-4"><div class="card-body"><h2 class="h5">Akun workspace</h2><div class="table-responsive"><table class="table"><thead><tr><th>Nama</th><th>Username</th><th>Email</th><th>Status</th></tr></thead><tbody><?php foreach($members as $member): ?><tr><td><?= e($member['name']) ?></td><td><?= e($member['username']) ?></td><td><?= e($member['email']) ?></td><td><?= e($member['state']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php if((int)$actor['is_platform_admin']===1&&(int)$actor['workspace_id']===1): ?>
<div class="card"><div class="card-body"><h2 class="h5">Registri akun platform</h2><p><a href="<?= e(base_url('account/settings')) ?>">Pengaturan pendaftaran & notifikasi platform</a></p><div class="table-responsive"><table class="table"><thead><tr><th>Nama</th><th>Email</th><th>Workspace</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($registry as $account): ?><tr><td><?= e($account['name']) ?></td><td><?= e($account['email']) ?></td><td><?= (int)$account['workspace_id'] ?></td><td><?= e($account['state']) ?></td><td><?php if($account['state']==='verified-pending-approval'): ?><form method="POST" action="<?= e(base_url('account/approve')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><button class="btn btn-sm btn-primary" type="submit">Setujui</button></form><?php endif; ?><?php if(!(int)$account['is_platform_admin']&&$account['state']!=='disabled'): ?><form method="POST" action="<?= e(base_url('account/disable')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Nonaktifkan akun</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php endif; ?></div>
